function fileData(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Falha ao ler arquivo.'));r.readAsDataURL(file);});}
async function importImage(file,face=false){if(!file||file.size>12e6)throw Error('Use um PNG de até 12 MB.');if(file.type&&file.type!=='image/png')throw Error('Importe PNG com transparência.');const src=await fileData(file);if(!src.startsWith('data:image/png;base64,'))throw Error('Arquivo não reconhecido como PNG.');const im=await image(src);if(im.width>8192||im.height>8192)throw Error('Imagem acima de 8192 px.');if(face&&!currentPart())throw Error('Selecione a peça que contém a face.');const id=unique(face?'face':'image',Object.keys(project.assets));images[id]=im;const accepted=edit(()=>{project.assets[id]={name:file.name,src,width:im.width,height:im.height};if(face){const p=currentPart(),key=$('expression').value;if(key==='normal')throw Error('Escolha Golpe, Dano ou Vitória para importar a variante.');if(im.width!==p.source[2]||im.height!==p.source[3])throw Error('A expressão deve ter o tamanho exato do recorte original: '+p.source[2]+' × '+p.source[3]+'.');p.faces||={};p.faces[key]={asset:id,source:[0,0,im.width,im.height]};}else{const part=unique('part',project.parts.map(p=>p.id)),w=32,h=w*im.height/im.width;project.parts.push({id:part,name:file.name.replace(/\.png$/i,''),asset:id,source:[0,0,im.width,im.height],rect:[32,32,w,h],pivot:[48,48],parent:null,z:project.parts.length,visible:true});selected=part;}});if(!accepted){delete images[id];throw Error('O PNG não foi importado. Confira a seleção e os limites do projeto.');}}
$('addImage').onclick=()=>$('fileImage').click();$('importFace').onclick=()=>$('fileFace').click();for(const [id,face]of [['fileImage',false],['fileFace',true]])$(id).onchange=async()=>{try{for(const file of $(id).files)await importImage(file,face);}catch(e){tell(e.message,true);}finally{$(id).value='';}};
$('open').onclick=()=>$('fileProject').click();$('fileProject').onchange=async()=>{try{const file=$('fileProject').files[0];if(!file)return;if(file.size>40e6)throw Error('Projeto acima de 40 MB.');const next=JSON.parse(await file.text());const audit=validate(next);if(!audit.ok&&!editableBlank(next,audit))throw Error(audit.errors.join('\n'));await load(next);}catch(e){tell('Não foi possível abrir: '+e.message,true);}finally{$('fileProject').value='';}};
async function embedded(){const result=clone(project);for(const a of Object.values(result.assets)){if(a.src.startsWith('data:'))continue;const r=await fetch(a.src);if(!r.ok)throw Error('Fonte ausente: '+a.src);a.src=await fileData(await r.blob());}return result;}
function download(name,content,type){const blob=content instanceof Blob?content:new Blob([content],{type}),url=URL.createObjectURL(blob),a=node('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);tell('Arquivo preparado: '+name);}
