function faceReport(){const notes=[],errors=[];for(const p of project.parts)for(const [face,ref]of Object.entries(p.faces||{})){
 if(ref.source[2]!==p.source[2]||ref.source[3]!==p.source[3]){errors.push(p.name+'/'+face+': tamanho diferente do corpo.');continue;}
 const a=pixels(p.asset,p.source),b=pixels(ref.asset,ref.source),width=p.source[2];let alpha=0,outside=0;
 for(let i=0;i<a.length;i+=4){if(a[i+3]!==b[i+3])alpha++;const x=i/4%width,y=Math.floor(i/4/width),inside=(p.faceWindows||[]).some(([sx,sy,w,h])=>x>=sx&&x<sx+w&&y>=sy&&y<sy+h);if(!inside&&(a[i]!==b[i]||a[i+1]!==b[i+1]||a[i+2]!==b[i+2]||a[i+3]!==b[i+3]))outside++;}
 if(alpha)errors.push(p.name+'/'+face+': alpha mudou em '+alpha+' pixels.');else notes.push('OK · '+p.name+'/'+face+': alpha idêntico.');
 if(outside)errors.push(p.name+'/'+face+': '+outside+' pixels alterados fora das janelas faciais.');else notes.push('OK · '+p.name+'/'+face+': pixels externos idênticos.');
 if(!p.faceWindows?.length)errors.push(p.name+': defina as janelas faciais no painel da peça.');
 }return {errors,notes};}
function exportReady(){if(draft)throw Error('Há uma pose não gravada. Use Gravar pose antes de salvar ou exportar.');const audit=validate(project);if(!audit.ok)throw Error(audit.errors.join('\n'));const faces=faceReport();if(faces.errors.length)throw Error(faces.errors.join('\n'));}
function buildFaceWindows(root,p){if(!Object.keys(p.faces||{}).length)return;const box=node('details'),title=node('summary','Janelas de registro facial');box.append(title);for(const [i,rect]of (p.faceWindows||[]).entries()){const grid=node('div',null,'field-grid');for(const [j,label]of ['Janela X','Janela Y','Janela L','Janela A'].entries())grid.append(field(label,rect[j],v=>edit(()=>p.faceWindows[i][j]=v),{step:'1',min:j>1?1:0}));const remove=node('button','Remover janela '+(i+1));remove.onclick=()=>edit(()=>p.faceWindows.splice(i,1));box.append(grid,remove);}const add=node('button','Adicionar janela facial');add.className='wide';add.onclick=()=>edit(()=>{p.faceWindows||=[];p.faceWindows.push([0,0,Math.max(1,Math.round(p.source[2]/4)),Math.max(1,Math.round(p.source[3]/4))]);});box.append(add,node('p','Pixels da face são medidos dentro do recorte original. A auditoria bloqueia mudanças fora destas janelas.','muted'));root.append(box);}

