$('removeClip').onclick=async()=>{if(!leaveDraft()||!await ask({title:'Excluir esta animação?',body:'As poses desta ação serão removidas do projeto. Você pode recuperar a ação usando Desfazer.',confirm:'Excluir animação'}))return;edit(()=>{if(Object.keys(project.clips).length<=1)throw Error('Mantenha ao menos uma ação.');delete project.clips[clipId];clipId=Object.keys(project.clips)[0];time=0;});};
addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||document.querySelector('dialog[open]'))return;if(assembly&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const step=e.shiftKey?10:1;edit(()=>nudgePart(project,selected,e.key==='ArrowLeft'?-step:e.key==='ArrowRight'?step:0,e.key==='ArrowUp'?-step:e.key==='ArrowDown'?step:0));return;}if(!e.ctrlKey&&!e.metaKey&&e.key.toLowerCase()==='v')$('moveTool').click();if(!e.ctrlKey&&!e.metaKey&&e.key.toLowerCase()==='p')$('pivotTool').click();if(e.code==='Space'){e.preventDefault();$('play').click();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();$(e.shiftKey?'redo':'undo').click();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();$('save').click();}});
addEventListener('resize',()=>{if(project)draw();});document.addEventListener('visibilitychange',()=>last=0);
function tick(ms){if(project){if(playing&&!document.hidden){if(last)time+=Math.min(.05,(ms-last)/1000)*Number($('speed').value);const c=project.clips[clipId];if(!c.loop&&time>=c.seconds){time=c.seconds;playing=false;$('play').textContent='▶ Reproduzir';}draw();}last=ms;}requestAnimationFrame(tick);}requestAnimationFrame(tick);

function ask({title,body,confirm:label,input=false}){return new Promise(resolve=>{const dialog=$('commandDialog');$('commandTitle').textContent=title;$('commandBody').textContent=body;$('commandConfirm').textContent=label;$('commandField').hidden=!input;$('commandInput').value='';$('commandInput').required=input;let answer=null;$('commandForm').onsubmit=e=>{e.preventDefault();if(input&&!$('commandInput').value.trim())return;answer=input?$('commandInput').value.trim():true;dialog.close();};$('commandCancel').onclick=()=>dialog.close();dialog.onclose=()=>resolve(answer);dialog.showModal();if(input)$('commandInput').focus();else $('commandCancel').focus();});}
function leaveDraft(){if(!draft)return true;tell('Grave a pose ou use Descartar ajuste no painel antes de continuar.',true);$('draftNotice').hidden=false;return false;}
function setPhase(next){if(!leaveDraft())return;phase=next;if(next==='review')solo=null;assembly=next==='assembly';playing=false;camera=null;refresh();document.querySelector('.inspector').scrollTop=0;}
function syncWorkflow(){
 if(phase!=='review')phase=assembly?'assembly':'animation';document.body.dataset.phase=phase;
 for(const [id,value]of [['stepAssembly','assembly'],['stepAnimation','animation'],['stepReview','review']]){if(value===phase)$(id).setAttribute('aria-current','step');else $(id).removeAttribute('aria-current');}
 const part=currentPart();$('projectSummary').textContent=project.parts.length+' peças · '+Object.keys(project.clips).length+' ações';
 $('contextHint').textContent=phase==='assembly'?'Monte a silhueta. Selecione uma peça, mova com as setas e marque o pivô.':phase==='animation'?'Escolha um instante → ajuste o canal → grave a pose. Espaço reproduz e pausa.':'Confira a leitura pequena, revise cada ação e execute a auditoria antes de exportar.';
 $('nextStep').textContent=phase==='assembly'?'Continuar para animação →':phase==='animation'?'Revisar e exportar →':'← Voltar à montagem';
 $('inspectorTitle').textContent=phase==='review'?'Revisão do projeto':phase==='animation'?'Animar '+(part?.name||'corpo inteiro'):(part?.name||'Corpo inteiro');
 $('selectionState').textContent=phase==='review'?'Exportações mantêm o projeto editável.':part?(part.locked?'Edição bloqueada':'Peça selecionada · '+part.source[2]+' × '+part.source[3]+' px'):'Movimento global da criatura';
 $('toggleLock').disabled=!part;$('toggleLock').textContent=part?.locked?'Desbloquear':'Bloquear';$('soloPart').disabled=!part;$('soloPart').textContent=solo?'Mostrar todas':'Isolar peça';$('soloPart').setAttribute('aria-pressed',String(!!solo));
 for(const id of ['remove','layerBack','layerFront'])$(id).disabled=!part||part.locked;
 $('centerPivot').disabled=!part||part.locked;$('trimAlpha').disabled=!part||part.locked||!!Object.keys(part.faces||{}).length;buildActionLibrary();$('emptyStage').hidden=!!project.parts.length;$('reviewPanel').open=true;
 $('reviewChecklist').replaceChildren(...[project.parts.length+' peças na montagem',Object.keys(project.clips).length+' ações para revisar',Object.values(project.clips).filter(c=>c.hitTime!=null).length+' ações com evento de impacto','Auditoria técnica + revisão visual necessárias'].map(text=>node('span',text)));
}
function updateDraftState(){
 $('draftNotice').hidden=!draft;$('pastePose').disabled=!copied||!!currentPart()?.locked;$('resetPose').disabled=!!currentPart()?.locked;
 $('stageBadge').textContent=draft?'AJUSTE NÃO GRAVADO':solo?'PEÇA ISOLADA · EXPORTAÇÃO USA TODAS AS PEÇAS':phase==='assembly'?(tool==='pivot'?'PIVÔ · CLIQUE NA ARTICULAÇÃO':'MONTAGEM · ARRASTE OU USE AS SETAS'):phase==='review'?'REVISÃO · PRÉVIA DO PROJETO':'ANIMAÇÃO · PRÉVIA DO PROJETO';
}
function buildActionLibrary(){const root=$('actionLibrary');root.replaceChildren(node('h2','Revisar ações'),node('p','Selecione cada ação e confira seus extremos antes da entrega.','muted'));for(const [id,c]of Object.entries(project.clips)){const b=node('button',c.label||id,'wide action-card');b.setAttribute('aria-pressed',String(id===clipId));b.append(node('small',c.seconds+' s · '+(c.loop?'contínua':'única')+(c.hitTime!=null?' · impacto '+c.hitTime+' s':'')));b.onclick=()=>{clipId=id;time=0;playing=false;refresh();};root.append(b);}}
function buildLayers(){
 const list=$('partList');list.replaceChildren();const query=$('partSearch').value.toLocaleLowerCase('pt-BR');
 for(const p of [{id:'root',name:'Corpo inteiro',z:null},...[...project.parts].sort((a,b)=>b.z-a.z)]){
  const row=node('div',null,'part'+(p.id===selected?' selected':'')+(p.locked?' locked':''));if(query&&!p.name.toLocaleLowerCase('pt-BR').includes(query)&&!p.id.toLowerCase().includes(query))row.classList.add('filtered');
  const button=node('button',null,'part-select');button.dataset.part=p.id;button.setAttribute('aria-pressed',String(p.id===selected));
  const thumb=node('canvas');thumb.width=thumb.height=64;thumb.setAttribute('aria-hidden','true');const g=thumb.getContext('2d');if(p.id==='root'){g.strokeStyle='#82dfc3';g.lineWidth=2;g.strokeRect(18,18,28,28);}else{const im=images[p.asset];if(im){const scale=52/Math.max(p.source[2],p.source[3]);g.drawImage(im,...p.source,32-p.source[2]*scale/2,32-p.source[3]*scale/2,p.source[2]*scale,p.source[3]*scale);}}
  const label=node('span',p.name);label.append(node('small',p.id==='root'?'Todos os canais':('Camada '+p.z+(p.parent?' · articula com '+(project.parts.find(q=>q.id===p.parent)?.name||p.parent):''))+(p.locked?' · bloqueada':'')));button.append(thumb,label);
  button.onclick=()=>{selected=p.id;camera=null;refresh();};row.append(button);
  if(p.id!=='root'){const eye=node('button',p.visible===false?'○':'◉','layer-toggle');eye.setAttribute('aria-label',(p.visible===false?'Mostrar ':'Ocultar ')+p.name);eye.title=eye.getAttribute('aria-label');eye.onclick=()=>edit(()=>p.visible=p.visible===false);row.append(eye);}
  list.append(row);
 }
 if(query&&![...list.children].some(e=>!e.classList.contains('filtered')))list.append(node('p','Nenhuma peça encontrada.','muted'));
}
function drawTimeline(c){
 $('keyCount').textContent=c.frames.length+' poses';$('jumpImpact').disabled=c.hitTime==null;
 const marks=$('keyMarkers');marks.replaceChildren();for(const f of timelineMarks(c)){const b=node('button',null,Math.abs(f.time-time)<.001?'current':'');b.style.left=f.percent+'%';b.title=f.time.toFixed(3)+' s';b.setAttribute('aria-label','Pose em '+f.time.toFixed(3)+' segundos');b.onclick=e=>{e.stopPropagation();seek(f.time);};marks.append(b);}
 const ticks=$('timelineTicks');ticks.replaceChildren();for(let i=0;i<=4;i++){const t=node('span',(c.seconds*i/4).toFixed(2)+' s');t.style.left=i*25+'%';ticks.append(t);}
 $('impactMarker').hidden=c.hitTime==null;$('impactMarker').style.left=100*(c.hitTime||0)/c.seconds+'%';
}
$('stepAssembly').onclick=()=>setPhase('assembly');$('stepAnimation').onclick=()=>setPhase('animation');$('stepReview').onclick=()=>setPhase('review');$('nextStep').onclick=()=>setPhase(phase==='assembly'?'animation':phase==='animation'?'review':'assembly');
$('partSearch').oninput=buildLayers;$('emptyImport').onclick=()=>$('addImage').click();$('emptyExample').onclick=()=>$('carcara').click();
$('toggleLock').onclick=()=>{const p=currentPart();if(p)edit(()=>p.locked=!p.locked,p.locked?'Peça desbloqueada.':'Peça bloqueada contra edições.');};
$('soloPart').onclick=()=>{solo=solo?null:currentPart()?.id;refresh();};
$('fit').onclick=()=>{camera=null;$('zoom').value='1';draw();tell('Criatura inteira enquadrada.');};
$('focusPart').onclick=()=>{const p=currentPart();if(!p)return tell('Selecione uma peça para focar.',true);const m=matrices(project,poseNow())[p.id],corners=[[p.rect[0],p.rect[1]],[p.rect[0]+p.rect[2],p.rect[1]],[p.rect[0],p.rect[1]+p.rect[3]],[p.rect[0]+p.rect[2],p.rect[1]+p.rect[3]]].map(([x,y])=>point(m,x,y)),xs=corners.map(q=>q.x),ys=corners.map(q=>q.y);camera={x:(Math.min(...xs)+Math.max(...xs))/2,y:(Math.min(...ys)+Math.max(...ys))/2,w:Math.max(...xs)-Math.min(...xs)+12,h:Math.max(...ys)-Math.min(...ys)+12};$('zoom').value='1';draw();tell('Peça enquadrada. Use Enquadrar para voltar.');};
$('previousKey').onclick=()=>seek(adjacentKey(project.clips[clipId],time,-1));$('nextKey').onclick=()=>seek(adjacentKey(project.clips[clipId],time,1));$('jumpImpact').onclick=()=>{if(project.clips[clipId].hitTime!=null)seek(project.clips[clipId].hitTime);};
$('timelineTrack').onclick=e=>{const r=$('timelineTrack').getBoundingClientRect();seek((e.clientX-r.left)/r.width*project.clips[clipId].seconds);};
$('copyPose').onclick=()=>{copied=copiedPose(project,clipId,time,selected,draft);updateDraftState();tell('Pose do canal copiada. Escolha outro instante ou peça e cole.');};
$('pastePose').onclick=()=>{if(!copied||currentPart()?.locked)return;playing=false;draft=pastedPose(project,clipId,time,selected,copied,draft);updatePoseFields();draw();};
$('resetPose').onclick=()=>{if(currentPart()?.locked)return;playing=false;draft=pastedPose(project,clipId,time,selected,identity(),draft);updatePoseFields();draw();};
$('commitDraft').onclick=()=>$('record').click();$('discardDraft').onclick=()=>{draft=null;updatePoseFields();draw();tell('Ajuste descartado; a pose gravada foi preservada.');};

$('viewport').addEventListener('dragover',e=>{e.preventDefault();$('viewport').classList.add('drop-target');});
$('viewport').addEventListener('dragleave',e=>{if(!$('viewport').contains(e.relatedTarget))$('viewport').classList.remove('drop-target');});
$('viewport').addEventListener('drop',async e=>{e.preventDefault();$('viewport').classList.remove('drop-target');if(!leaveDraft())return;try{const files=[...e.dataTransfer.files];if(!files.length)return;if(files.length===1&&files[0].name.toLowerCase().endsWith('.json')){if(files[0].size>40e6)throw Error('Projeto acima de 40 MB.');await load(JSON.parse(await files[0].text()));}else{setPhase('assembly');for(const file of files)await importImage(file);tell(files.length+' PNG(s) importados. Ajuste os encaixes e pivôs.');}}catch(e){tell(e.message,true);}});
addEventListener('beforeunload',e=>{if(draft){e.preventDefault();e.returnValue='';}});
try{const requestedPreset=new URLSearchParams(location.search).get('preset');let cached;try{cached=localStorage.getItem(STORE);if(location.search==='?preset=kael'&&cached&&JSON.parse(cached).avatar?.kind!=='kael-modular-v1')cached=null;}catch{}let cachedCreature,cachedRevision,cachedRigRevision;try{const previous=JSON.parse(cached||'null');cachedCreature=previous?.creatureId;cachedRevision=previous?.artRevision;cachedRigRevision=previous?.rigRevision||0;}catch{cached=null;}if(requestedPreset==='capimansa'){await load(cachedCreature==='capimansa'&&cachedRevision===2&&cachedRigRevision===2?JSON.parse(cached):await createCapimansa(),{remember:false});}else if(requestedPreset==='micofolha'){await load(cachedCreature==='micofolha'&&cachedRevision===2&&cachedRigRevision===2?JSON.parse(cached):await createMicofolha(),{remember:false});}else if(requestedPreset==='guaravento'){await load(cachedCreature==='guaravento'&&cachedRevision===2&&cachedRigRevision===1?JSON.parse(cached):await createGuaravento(),{remember:false});}else if(requestedPreset==='nozinho'){await load(cachedCreature==='nozinho'&&cachedRevision===2?JSON.parse(cached):await createNozinho(),{remember:false});}else if(['lacertubo','lacertubo-v2'].includes(requestedPreset)){await load(cachedCreature===requestedPreset?JSON.parse(cached):await createGuardian(requestedPreset),{remember:false});}else if(Object.hasOwn(BASIC_CREATURES,requestedPreset)&&(cachedCreature!==requestedPreset||cachedRevision!==2||(requestedPreset==='rabbito'&&cachedRigRevision!==1))){if(cached&&cachedCreature===requestedPreset)try{localStorage.setItem(STORE+'-archive-'+cachedCreature+'-r'+cachedRevision,cached);}catch{}await load(await createBasic(requestedPreset),{remember:false});}else if(cached){try{const p=JSON.parse(cached),audit=validate(p);if(!audit.ok&&!editableBlank(p,audit))throw Error(audit.errors.join(' '));await load(p,{remember:false});tell('Projeto recuperado deste navegador.');}catch(e){await preset();tell('Recuperação antiga não pôde ser aberta; exemplo carregado. '+e.message,true);}}else if(location.search==='?preset=kael')await load(await createKael(),{remember:false});else await preset();}catch(e){$('loading').hidden=false;$('loading').textContent='Não foi possível carregar o ateliê: '+e.message;const retry=node('button','Tentar novamente');retry.onclick=()=>location.reload();$('loading').append(retry);tell(e.message,true);}

